const ELEMENT_PROP_KEYS = new Set(["theme","before","word","after","wrongWord","stagger","accent","fontFamily","ink","background","scale","delay","speed"]);

const ELEMENT_PROP_DEFAULTS: Record<string, unknown> = {
  theme: "dark",
  before: "Launch ",
  word: "videos",
  after: ", in code.",
  wrongWord: "slides",
  stagger: 4,
